def name_operands(region,address,operation):
 if region!='D3D' or address!=0xDD4F:return operation
 data={0xC27B:'PreviewFaceGateState.Value.RejectCode',0xC23B:'PreviewFillMode.Value.Index',0xC22B:'PreviewContourSize.Value.ByteCount',0xC26F:'PreviewEdgeMode.Value.PixelOpcode',0xC24B:'PreviewEdgeEndpoints.Value.StartPoint',0xC24D:'PreviewEdgeEndpoints.Value.EndPoint',0xC24E:'PreviewEdgeEndpoints.Value.EndPoint + 1',0xDE34:'PreviewEdgeRasterState.MaskOffset'}
 for pointer,label in data.items():operation=operation.replace('(#'+format(pointer,'04X')+')','(@'+label+')')
 for pointer,name in ((0xDFA6,'ComputePreviewFaceOrientation'),(0xD41B,'FillPreviewPolygon'),(0xDE1C,'RasterizePreviewEdge')):operation=operation.replace('#'+format(pointer,'04X'),'@D3D.'+name+'.Entry')
 operation=operation.replace('#DD4F','@D3D.RenderPreviewInsideFaces.Entry')
 for (_,pointer),label in LABELS.items():operation=operation.replace('#'+format(pointer,'04X'),'@D3D.RenderPreviewInsideFaces.'+label)
 for old,label in (('AND #0F','CountMask'),('AND #07','FillMask'),('AND #30','LineModeMask'),('CP #10','OrMode'),('LD DE, #38A9','XorPair'),('LD DE, #30A1','AndPair'),('LD DE, #38B1','OrPair'),('LD A, #B0','SetMaskLow'),('LD A, #B8','ClearMaskLow')):
  operation=operation.replace(old,old.rsplit('#',1)[0]+'@PreviewFaceStreamConst.'+label)
 operation=operation.replace('BIT 6, (HL)','BIT @PreviewFaceStreamConst.GateBit, (HL)').replace('LD B, #C6','LD B, @PreviewFaceMathConst.VertexPage').replace('LD D, #C6','LD D, @PreviewFaceMathConst.VertexPage')
 operation=operation.replace('LD DE, #C800','LD DE, @PreviewPolygonPrepConst.FirstPointRow - 1')
 return operation
